{
  "name": "R&S HMP4040四通道直流电源",
  "name_en": "R&S HMP4040 Four-Channel DC Power Supply",
  "manufacturer": "Rohde & Schwarz",
  "description": "一款可编程四通道台式直流电源，用于在实验中为电路、传感器或测试模块提供稳定电压与限流输出，并读取各通道的电压、电流和保护状态。",
  "description_en": "A programmable four-channel bench DC power supply used in laboratories to provide stable voltage and current-limited outputs for circuits, sensors, or test modules, while monitoring channel voltage, current, and protection status.",
  "tag_hints": [
    "programmable DC power supply",
    "four-channel output",
    "voltage sourcing",
    "current limit",
    "bench power supply",
    "electrical testing"
  ],
  "actions": [
    {
      "action_name": "auto-init",
      "description": "初始化电源并建立通信。",
      "description_en": "Initialize the power supply and establish communication."
    },
    {
      "action_name": "auto-reinit",
      "description": "重新初始化电源通信与状态。",
      "description_en": "Reinitialize communication with the power supply and refresh its state."
    },
    {
      "action_name": "auto-write",
      "description": "向电源发送原始控制命令。",
      "description_en": "Send a raw control command to the power supply."
    },
    {
      "action_name": "auto-ask",
      "description": "向电源发送查询命令并请求返回结果。",
      "description_en": "Send a query command to the power supply and request a response."
    },
    {
      "action_name": "auto-read",
      "description": "读取电源返回的数据。",
      "description_en": "Read data returned by the power supply."
    },
    {
      "action_name": "auto-set_channel",
      "description": "选择当前操作的输出通道。",
      "description_en": "Select the active output channel."
    },
    {
      "action_name": "auto-get_channel",
      "description": "读取当前选中的输出通道。",
      "description_en": "Get the currently selected output channel."
    },
    {
      "action_name": "auto-set_enable",
      "description": "打开或关闭指定通道的输出。",
      "description_en": "Enable or disable the output of the specified channel."
    },
    {
      "action_name": "auto-get_name",
      "description": "读取电源设备名称或型号标识。",
      "description_en": "Get the power supply device name or model identification."
    },
    {
      "action_name": "auto-get_current",
      "description": "读取指定通道的实际输出电流。",
      "description_en": "Get the actual output current of the specified channel."
    },
    {
      "action_name": "auto-get_voltage",
      "description": "读取指定通道的实际输出电压。",
      "description_en": "Get the actual output voltage of the specified channel."
    },
    {
      "action_name": "auto-get_set_voltage",
      "description": "读取指定通道设定的输出电压值。",
      "description_en": "Get the configured voltage setpoint of the specified channel."
    },
    {
      "action_name": "auto-get_current_limit",
      "description": "读取指定通道的电流限制值。",
      "description_en": "Get the current limit of the specified channel."
    },
    {
      "action_name": "auto-set_voltage",
      "description": "设置指定通道的输出电压。",
      "description_en": "Set the output voltage of the specified channel."
    },
    {
      "action_name": "auto-set_current_limit",
      "description": "设置指定通道的电流限制。",
      "description_en": "Set the current limit of the specified channel."
    },
    {
      "action_name": "auto-reset_trip",
      "description": "复位电源的保护跳闸状态。",
      "description_en": "Reset the protection trip state of the power supply."
    }
  ]
}

